const MATERIAL_MODEL: u32 = 1u;
const MATERIAL_FOG: bool = false;
fn material_surface(in: SurfaceInput) -> SurfaceOutput {
  var out = surface_defaults();
  let v0: vec2f = in.instance_params.xy;
  let v1: vec2f = in.instance_params.zw;
  let v2: vec2f = (in.uv * v1);
  let v3: vec2f = (v0 + v2);
  let v4: f32 = in.instance_params.x;
  let v5: f32 = abs(v4);
  let v6: f32 = in.instance_params.z;
  let v7: f32 = abs(v6);
  let v8: f32 = (v5 + v7);
  let v9: f32 = step(0.000001, v8);
  let v10: vec2f = vec2f(v9);
  let v11: vec2f = mix(in.uv, v3, v10);
  let v12: vec2f = vec2f(-1.0);
  let v13: f32 = step(v4, -0.5);
  let v14: vec2f = vec2f(v13);
  let v15: vec2f = mix(v11, v12, v14);
  let v16: vec2f = vec2f(2048.0, 1024.0);
  let v17: vec2f = (v15 * v16);
  let v18: vec4f = pixel_load(v17);
  let v19: vec3f = v18.xyz;
  let v20: vec3f = in.color.xyz;
  let v21: vec3f = in.instance_params.yzw;
  let v22: vec3f = vec3f(v13);
  let v23: vec3f = mix(v20, v21, v22);
  let v24: f32 = v15.x;
  let v25: f32 = step(v24, -0.5);
  let v26: vec3f = vec3f(v25);
  let v27: vec3f = mix(v19, v23, v26);
  let v28: vec3f = vec3f(0.03137254901960784, 0.047058823529411764, 0.10588235294117647);
  let v29: vec3f = (v27 * 0.09803921568627451);
  let v30: vec3f = (v28 + v29);
  let v31: vec4f = material_global(0u);
  let v32: f32 = v31.z;
  let v33: f32 = in.world_pos.x;
  let v34: f32 = step(108.0, v33);
  let v35: f32 = (v32 * v34);
  let v36: f32 = step(v33, 660.0);
  let v37: f32 = (v35 * v36);
  let v38: f32 = v31.y;
  let v39: f32 = in.world_pos.y;
  let v40: f32 = -(v39);
  let v41: f32 = (v40 + 720.0);
  let v42: f32 = step(v38, v41);
  let v43: f32 = (v37 * v42);
  let v44: f32 = (v38 + 82.0);
  let v45: f32 = step(v41, v44);
  let v46: f32 = (v43 * v45);
  let v47: vec3f = vec3f(v46);
  let v48: vec3f = mix(v27, v30, v47);
  let v49: f32 = v31.x;
  let v50: f32 = -(v49);
  let v51: f32 = (v50 + 1.0);
  let v52: vec3f = (v48 * v51);
  let v53: vec3f = pixel_srgb_to_linear(v52);
  let v54: f32 = v18.w;
  let v55: f32 = mix(v54, 1.0, v25);
  out.base_color = v53;
  out.alpha = v55;
  return out;
}
